import"./chunk-2NFLSA4Y.js";var a={electricCharge:{theory:{concept:"[[Electric charge is a physical quantity that describes the ability of a body to take part in electromagnetic interactions; it is measured in coulombs (C).]] The charge of any body is a whole multiple of the elementary charge e \u2248 1.6 \xB7 10\u207B\xB9\u2079 C: q = (N\u209A \u2212 N\u2091) \xB7 e, so a body is charged when it has more or fewer electrons than protons. In a closed system the total charge stays constant \u2014 the law of conservation of charge."},section:{particles:{title:"Where does charge come from?",text:"Protons have positive charge, electrons have negative charge, and neutrons have no electric charge. A proton and an electron carry charges of equal magnitude and opposite sign. An object with equal numbers of protons and electrons has zero net charge: it is electrically neutral. Neutral does not mean that it contains no charged particles."},repulsion:{title:"Like charges repel: + and +, or \u2212 and \u2212",text:"[[Two positive charges repel one another, as do two negative charges.]] Each experiences a force directed away from the other. If free to move, initially stationary charges begin to move apart."},attraction:{title:"Opposite charges attract: + and \u2212",text:"[[A positive and a negative charge attract one another.]] Each experiences a force directed toward the other. The forces on the two charges are equal in magnitude and opposite in direction, even when the amounts of charge differ. Their motions also depend on their masses and other forces."},charging:{title:"Charging transfers electrons",text:"When ordinary objects are rubbed together, electrons can transfer from one material to the other. An object that gains electrons becomes negatively charged; one that loses electrons becomes positively charged. Rubbing does not create charge: the total charge of an isolated system is conserved. Protons remain bound in atomic nuclei."},neutral:{title:"A neutral object can also be attracted",text:"A charged object can slightly redistribute charges in a nearby neutral object. Opposite charge becomes closer, while like charge is farther away. The closer attraction can outweigh the farther repulsion, giving a net attraction. This is called polarization; the neutral object need not gain or lose electrons overall. Attraction alone therefore does not prove that two objects have opposite net charges."},try:{title:"Try it: a plastic ruler and paper",text:"Rub a dry plastic ruler with a dry cloth and bring it near small scraps of paper without touching them. The ruler may attract the initially neutral paper by redistributing its charges. Results depend on the materials and humidity. This is static electricity; no battery is needed."},check:{title:"Check your understanding",text:"Two negatively charged objects repel. A positive and a negative charge attract. If an object gains electrons, it becomes more negative. If a charged ruler attracts paper, the paper may still have zero net charge. Can you explain each result using the ideas above?"}},formula:{signs:"Positive, negative and zero net charge",netCharge:"Net charge: N\u209A is the number of protons, N\u2091 the number of electrons, and e = 1.602176634 \xD7 10\u207B\xB9\u2079 C",equal:"The forces on the two balls are equal in size and opposite in direction (Newton\u2019s third law)",coulomb:"Coulomb\u2019s law: size of the electric force between two point charges",energy:"Electric potential energy of the pair (positive for repulsion, negative for attraction)"},variable:{charge:"Net electric charge",distance:"Distance between the centres of the charges",force:"Electric force on each ball",k:"Coulomb constant, k \u2248 8.99 \xD7 10\u2079 N\xB7m\xB2/C\xB2"},assumption:{scope:"The balls are treated as point charges. Real objects can redistribute charge; the attraction of a neutral object needs the polarization explanation and is not simulated here.",distance:"The force gets weaker quickly as the distance grows: at twice the distance it is four times smaller. This is Coulomb\u2019s law, studied in more detail in the next topic.",insulators:"The balls are insulators: their charge stays on them, even when they touch.",track:"The balls roll on a smooth horizontal track without friction or air resistance, so gravity does not affect the motion.",arrows:"Force arrows grow with the force but are not to scale; read the exact value on the label."},param:{charge1:"Charge of ball 1",charge2:"Charge of ball 2",distance:"Starting distance",mass1:"Mass of ball 1",mass2:"Mass of ball 2",fixFirst:"Hold ball 1 in place",timeStep:"Simulation timestep"},hint:{charge:"Plus (+) means the ball lost electrons, minus (\u2212) means it gained electrons, 0 means it is neutral.",fixFirst:"A stand holds ball 1. The electric force on it does not disappear \u2014 the stand balances it."},preset:{positive:"Positive",neutral:"Neutral",negative:"Negative"},measure:{separation:"Distance between the balls",force:"Electric force on each ball",speed1:"Speed of ball 1",speed2:"Speed of ball 2",acceleration1:"Acceleration of ball 1",acceleration2:"Acceleration of ball 2",potentialEnergy:"Electric potential energy"},view:{attraction:"Attraction",repulsion:"Repulsion",none:"No electric force",touching:"The balls touched"},graph:{force:"Force against distance",energy:"Energy during the motion"},challenge:{repel:{title:"Two negatives",description:"Give both balls a negative charge and watch them push each other to the ends of the track.",hint:"Like charges repel: \u2212 and \u2212."},attract:{title:"Unequal partners",description:"Make the balls attract and touch, using charges of different size.",hint:"Use opposite signs. Look at the force arrows: are they still equal?"},neutral:{title:"Nothing happens",description:"Make one ball neutral and the other charged. Do the balls move?",hint:"Set one charge to 0."},strong:{title:"A strong push",description:"Set up repulsion with a starting force of at least 0.1 N.",hint:"Increase the charges or bring the balls closer together."},heavyLight:{title:"Heavy and light",description:"Make the balls attract while ball 1 is at least three times heavier than ball 2. Which one moves more?",hint:"The forces are equal, but a lighter ball speeds up more."},fast:{title:"Launch",description:"Push ball 2 off the track at a speed of at least 1 m/s.",hint:"Large like charges, a small starting distance and a light ball 2."}}}},r={sim:a};export{r as default,a as sim};
